options.css:
* { box-sizing: border-box; font-family: 'Inter', sans-serif; }
.wrap { padding: 12px; overflow-x: auto; }
table { border-collapse: collapse; width: 100%; table-layout: auto; }
th, td { border: 1px solid #333; padding: 7px 11px; text-align: center; font-size: 12px; white-space: nowrap; }
th { background: #1e2433; color: #c5cedd; font-weight: 600; }
thead th:first-child { width: 130px; min-width: 100px; max-width: 160px; text-align: left; }
td.cl { text-align: left; font-weight: 500; color: #c5cedd; background: #1e2433; width: 130px; min-width: 100px; max-width: 160px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
td.pass { background: #1a3a2a; color: #73bf69; cursor: pointer; text-decoration: underline; }
td.fail { background: #3d1a1a; color: #f2495c; cursor: pointer; font-weight: 700; text-decoration: underline; }
td.warn { background: #3d2a0a; color: #f89520; cursor: pointer; font-weight: 700; text-decoration: underline; }
td.nd { background: #23283a; color: #555f6b; }
td.pass:hover { background: #1f4a33; }
td.fail:hover { background: #501f1f; }
td.warn:hover { background: #4f3510; }
.legend { margin-top: 8px; display: flex; gap: 14px; font-size: 11px; color: #8e9daa; }
.dot { display: inline-block; width: 9px; height: 9px; border-radius: 50%; margin-right: 4px; }
.gd { background:#73bf69; } .rd { background:#f2495c; } .or { background:#f89520; } .gy { background:#555f6b; }

options.onRender:
function safeVals(f) {
  if (!f || f.values == null) return [];
  const v = f.values;
  if (typeof v.toArray === 'function') return v.toArray();
  if (Array.isArray(v)) return v;
  const len = typeof v.length === 'number' ? v.length : 0;
  return Array.from({length: len}, (_, i) => typeof v.get === 'function' ? v.get(i) : v[i]);
}
const el = htmlNode.querySelector('#mc');
if (!data.series || !data.series[0]) { el.innerHTML = '<p style="color:#8e9daa;padding:20px">No audit data yet.</p>'; return; }
const frame = data.series[0];
if (!frame.fields || !frame.fields.length) { el.innerHTML = '<p style="color:#8e9daa;padding:20px">Empty response.</p>'; return; }
const F = {};
frame.fields.forEach(f => { F[f.name] = safeVals(f); });
const n = (F.client_name || []).length;
const rows = [];
for (let i = 0; i < n; i++) {
  const d = String(F.audit_date ? F.audit_date[i] : '');
  if (!d) continue;
  rows.push({ client: F.client_name[i], date: d, shift: F.shift[i], p1: Number(F.p1_fail_count ? F.p1_fail_count[i] : 0), p2: Number(F.p2_fail_count ? F.p2_fail_count[i] : 0), status: F.overall_status ? F.overall_status[i] : 'PASS' });
}
const dSet = new Set(), cSet = new Set();
rows.forEach(r => { dSet.add(r.date); cSet.add(r.client); });
const dates = Array.from(dSet).sort();
const clients = Array.from(cSet).sort();
const lut = {};
rows.forEach(r => { lut[r.client+'|'+r.date+'|'+r.shift] = r; });
const base = '/vui/d/ng-audit-detail';
let h = '<table><thead><tr><th>Customer</th>';
dates.forEach(d => { h += `<th colspan="2">${d}</th>`; });
h += '</tr><tr><th></th>';
dates.forEach(() => { h += '<th>BOD</th><th>EOD</th>'; });
h += '</tr></thead><tbody>';
clients.forEach(c => {
  h += `<tr><td class="cl" title="${c}">${c}</td>`;
  dates.forEach(d => {
    ['BOD','EOD'].forEach(s => {
      const r = lut[c+'|'+d+'|'+s];
      if (!r) { h += '<td class="nd">—</td>'; return; }
      const cls = r.p1 > 0 ? 'fail' : (r.status === 'FAIL' ? 'warn' : 'pass');
      const lbl = cls === 'pass' ? 'PASS' : 'FAIL';
      const p = `var-client=${encodeURIComponent(c)}&var-date=${d}&var-shift=${s}`;
      h += `<td class="${cls}" onclick="window.open('${base}?${p}','_blank')">${lbl}</td>`;
    });
  });
  h += '</tr>';
});
h += '</tbody></table>';
el.innerHTML = h;
